describe('Debounced Search Functionality', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').as('searchInput');
    cy.get('[data-testid="search-results"]').as('searchResults');
  });

  it('should trigger search only after 300ms of inactivity', () => {
    const searchTerm = 'cypress';
    let searchCallCount = 0;

    cy.intercept('GET', '**/api/search*', (req) => {
      searchCallCount++;
      req.reply({
        statusCode: 200,
        body: {
          results: [
            { id: 1, title: 'Cypress Testing' },
            { id: 2, title: 'Cypress Documentation' }
          ]
        }
      });
    }).as('searchRequest');

    cy.get('@searchInput').type('c', { delay: 50 });
    cy.get('@searchInput').type('y', { delay: 50 });
    cy.get('@searchInput').type('p', { delay: 50 });
    cy.get('@searchInput').type('r', { delay: 50 });
    cy.get('@searchInput').type('e', { delay: 50 });
    cy.get('@searchInput').type('s', { delay: 50 });
    cy.get('@searchInput').type('s', { delay: 50 });

    cy.wait(350);

    cy.get('@searchResults').should('be.visible');
    cy.get('@searchResults').should('contain', 'Cypress Testing');
    cy.get('@searchResults').should('contain', 'Cypress Documentation');

    cy.get('@searchRequest').its('request.url').should('include', searchTerm);
  });

  it('should debounce multiple rapid searches and only execute the final one', () => {
    cy.intercept('GET', '**/api/search*', (req) => {
      req.reply({
        statusCode: 200,
        body: {
          results: [{ id: 1, title: 'Result for ' + req.url }]
        }
      });
    }).as('searchRequest');

    cy.get('@searchInput').clear().type('test', { delay: 30 });
    cy.wait(100);
    cy.get('@searchInput').clear().type('testing', { delay: 30 });
    cy.wait(100);
    cy.get('@searchInput').clear().type('testing framework', { delay: 30 });

    cy.wait(350);

    cy.get('@searchRequest').then((interception) => {
      expect(interception.request.url).to.include('testing framework');
    });

    cy.get('@searchResults').should('be.visible');
  });

  it('should not trigger search if user continues typing within 300ms', () => {
    let requestCount = 0;

    cy.intercept('GET', '**/api/search*', (req) => {
      requestCount++;
      req.reply({
        statusCode: 200,
        body: { results: [] }
      });
    }).as('searchRequest');

    cy.get('@searchInput').type('a', { delay: 100 });
    cy.get('@searchInput').type('b', { delay: 100 });
    cy.get('@searchInput').type('c', { delay: 100 });

    cy.wait(150);

    cy.get('@searchRequest').should('not.exist');

    cy.wait(250);

    cy.get('@searchRequest').should('exist');
  });

  it('should handle empty search input gracefully', () => {
    cy.intercept('GET', '**/api/search*', (req) => {
      req.reply({
        statusCode: 200,
        body: { results: [] }
      });
    }).as('searchRequest');

    cy.get('@searchInput').type('test', { delay: 50 });
    cy.wait(350);

    cy.get('@searchInput').clear();
    cy.wait(350);

    cy.get('@searchResults').should('not.contain', 'Result');
  });

  it('should reset debounce timer on each keystroke', () => {
    cy.intercept('GET', '**/api/search*', (req) => {
      req.reply({
        statusCode: 200,
        body: { results: [{ id: 1, title: 'Test Result' }] }
      });
    }).as('searchRequest');

    cy.get('@searchInput').type('t', { delay: 100 });
    cy.wait(200);
    cy.get('@searchInput').type('e', { delay: 100 });
    cy.wait(200);
    cy.get('@searchInput').type('s', { delay: 100 });
    cy.wait(200);
    cy.get('@searchInput').type('t', { delay: 100 });

    cy.wait(350);

    cy.get('@searchRequest').should('have.been.calledOnce');
    cy.get('@searchResults').should('contain', 'Test Result');
  });
});
